const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Function to mask clouds in Landsat 8/9 C2 L2 data.
function maskL8sr(image) {
  const qa = image.select('QA_PIXEL');
  // Bits 3 and 4 are cloud shadow and cloud, respectively.
  const cloudShadowBitMask = (1 << 3);
  const cloudsBitMask = (1 << 5);
  // Both flags should be set to zero, indicating clear conditions.
  const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
  return image.updateMask(mask);
}

// Function to convert ST band to Celsius.
function toCelsius(image) {
    const tempInC = image.select('ST_B10').multiply(0.00341802).add(149.0).subtract(273.15);
    return image.addBands(tempInC.rename('surface_temp_celsius'));
}

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const eruptionPoint = ee.Geometry.Point([-22.413665983340525, 63.8577134531586]);
    const grindavikPoint = ee.Geometry.Point([-22.4333, 63.8416]); // Center of Grindavik
    const date = '2024-01-16';

    // 2. Data Acquisition & Check
    let collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterDate(date, ee.Date(date).advance(1, 'day'))
        .filterBounds(eruptionPoint.buffer(5000));

    let collectionSize = collection.size().getInfo();

    if (collectionSize === 0) {
        console.log('No Landsat 9 images found. Checking Landsat 8.');
        collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
            .filterDate(date, ee.Date(date).advance(1, 'day'))
            .filterBounds(eruptionPoint.buffer(5000));
        collectionSize = collection.size().getInfo();
    }

    console.log(`Images found for ${date}: ${collectionSize}`);
    if (collectionSize === 0) {
        console.log('Evidence: No Landsat images available for the specified date and location.');
        console.log('C1');
        return;
    }

    // 3. Processing
    const processedCollection = collection.map(maskL8sr).map(toCelsius);
    const image = processedCollection.mosaic().select('surface_temp_celsius');

    // Use a small buffer around the point to get an average of the area, making it more robust.
    const scale = 30; // Native resolution of thermal bands.

    // 4. Calculation
    const eruptionTempDict = image.reduceRegion({
        reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
        geometry: eruptionPoint.buffer(scale),
        scale: scale,
        maxPixels: 1e9
    });

    const grindavikTempDict = image.reduceRegion({
        reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
        geometry: grindavikPoint.buffer(scale * 2), // Larger buffer for the town
        scale: scale,
        maxPixels: 1e9
    });

    const eruptionTemp = eruptionTempDict.get('surface_temp_celsius_mean').getInfo();
    const eruptionPixels = eruptionTempDict.get('surface_temp_celsius_count').getInfo();

    const grindavikTemp = grindavikTempDict.get('surface_temp_celsius_mean').getInfo();
    const grindavikPixels = grindavikTempDict.get('surface_temp_celsius_count').getInfo();

    // 5. Validation & Final Answer
    console.log(`Eruption Point Valid Pixels: ${eruptionPixels}`);
    console.log(`Grindavik Point Valid Pixels: ${grindavikPixels}`);

    if (eruptionPixels === 0 || grindavikPixels === 0) {
        console.log('Evidence: No valid (cloud-free) pixels found at one or both locations.');
        console.log('C2');
        return;
    }

    if (eruptionTemp === null || grindavikTemp === null) {
        console.log('Evidence: Temperature calculation failed for one or both points.');
        console.log('C3');
        return;
    }

    console.log(`Eruption Point Temperature (°C): ${eruptionTemp.toFixed(2)}`);
    console.log(`Grindavik Temperature (°C): ${grindavikTemp.toFixed(2)}`);

    if (eruptionTemp > grindavikTemp) {
        console.log('Evidence: The temperature at the specified point was higher than in Grindavik.');
        console.log('A');
    } else {
        console.log('Evidence: The temperature at the specified point was not higher than in Grindavik.');
        console.log('B');
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log('D');
});
